import pytest

from sales_dashboard.loader import daily_conversion_counts, dedupe_sessions, parse_session_log
from sales_dashboard.metrics import (
    conversion_rate, conversion_rate_by_group, conversions_in_window,
    longest_conversion_streak, pooled_conversion_rate,
)
from sales_dashboard.report import campaign_summary, top_converting_groups


def test_conversion_rate_counts_none_as_not_converted():
    assert conversion_rate([{"converted": True}, {"converted": None}]) == 0.5
    assert conversion_rate([]) == 0.0


def test_dedupe_keeps_last_occurrence_then_sorts():
    events = parse_session_log(["b,7,0", "c,1,1", "b,2,1", "a,2,0"])
    assert dedupe_sessions(events) == [events[1], events[3], events[2]]


def test_parse_skips_comments_and_blank_lines_and_trims_fields():
    lines = ["", "  \n", "  # ignored", " a , 3 , 0 ", "b, 4,  "]
    assert parse_session_log(lines) == [
        {"id": "a", "day": 3, "converted": False},
        {"id": "b", "day": 4, "converted": None},
    ]


@pytest.mark.parametrize("bad_line", ["a,1", "a,1,0,extra", "a,day,1"])
def test_parse_reports_original_line_number(bad_line):
    with pytest.raises(ValueError, match=r"line 4\b"):
        parse_session_log(["", " # comment", "ok,1,1", bad_line])


def test_daily_counts_and_window_boundaries():
    events = parse_session_log(["a,1,1", "b,2,1", "c,2,1", "d,4,0", "e,5,1"])
    assert daily_conversion_counts(events, 2, 4) == [2, 0, 0]
    assert daily_conversion_counts(events, 4, 2) == []
    assert conversions_in_window([2, 0, 1], 2) == 1
    assert conversions_in_window([2, 0, 1], 0) == 0
    assert conversions_in_window([2, 0, 1], 4) == 3


def test_summary_weights_sessions_and_uses_calendar_days():
    groups = {"a": parse_session_log(["a,1,1"]), "b": parse_session_log(["b,4,1", "c,5,0"]), "c": []}
    assert pooled_conversion_rate(groups) == 2 / 3
    assert campaign_summary(groups, 2) == {"rate": 0.667, "recent": 1, "groups": 2}
    assert campaign_summary({"empty": []}, 2) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_group_rankings_and_rate_order():
    groups = {"z": [{"converted": True}], "empty": [], "b": [{"converted": False}], "a": [{"converted": True}]}
    assert top_converting_groups(groups, 2) == ["a", "z"]
    assert top_converting_groups(groups, 5) == ["a", "z", "b"]
    assert list(conversion_rate_by_group(groups).items()) == [("a", 1.0), ("b", 0.0), ("empty", None), ("z", 1.0)]


def test_streak_resets_on_nonpositive_days():
    assert longest_conversion_streak([2, -1, 1, 2, 0, 1]) == 2
    assert longest_conversion_streak([]) == 0
